import java.util.*;

public class Main {

    static final int DIMENSION = 32;
    static final int MOD = 1000000007;
    static final int MAX_D = 64;
    static final int MAX_K = 32;

    static int sum_mod(int a, int b) {
        int s = a + b;
        if (s >= MOD) s -= MOD;
        return s;
    }

    static int product_mod(int a, int b) {
        return (int)((long)a * b % MOD);
    }

    static class Matrix {
        int[][] mat;

        public Matrix() {
            mat = new int[DIMENSION][DIMENSION];
            for (int i = 0; i < DIMENSION; ++i) {
                Arrays.fill(mat[i], 0);
            }
        }

        public int[] getRow(int i) {
            return mat[i];
        }

        static Matrix multiply(Matrix A, Matrix B) {
            Matrix R = new Matrix();
            for (int i = 0; i < DIMENSION; ++i) {
                for (int j = 0; j < DIMENSION; ++j) {
                    int sum = 0;
                    for (int k = 0; k < DIMENSION; ++k) {
                        sum = sum_mod(sum, product_mod(A.mat[i][k], B.mat[k][j]));
                    }
                    R.mat[i][j] = sum;
                }
            }
            return R;
        }
    }

    static int k;

    static class State {
        Matrix[] f = new Matrix[MAX_D];

        State() {}
    }

    static Matrix[][] f = new Matrix[MAX_D][k + 1];

    static Matrix buildMatrix(int n, int offset) {
        Matrix M = new Matrix();
        for (int i = 0; i <= k; ++i)
            for (int j = 0; j <= k; ++j) {
                int ni = (i == k) ? i : (i + offset) % k;
                int nj = (j == k) ? j : (j + offset) % k;
                M.mat[ni][nj] = f[n][i][j];
            }
        return M;
    }

    static int digit_sum(long n) {
        int sum = 0;
        while (n > 0) {
            sum += n % k;
            n /= k;
        }
        return sum % k;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int base = sc.nextInt();
        k = base;

        int digits_count = 0;
        long temp = n;
        while (temp > 0) {
            temp /= k;
            ++digits_count;
        }

        Matrix identity = new Matrix();
        for (int i = 0; i <= k; ++i)
            identity.mat[i][i] = 1;

        f[0] = new Matrix[MAX_D];
        for (int i = 0; i <= k; ++i) {
            f[0] = new Matrix[Math.max(digits_count + 1, 1)];
            f[0][i] = new Matrix();
            f[0][i] = identity;
            f[0][i].mat[i][0] = 1;
        }

        for (int i = 1; i < digits_count; ++i) {
            for (int j = 0; j <= k; ++j) {
                if (f[i] == null) {
                    f[i] = new Matrix[k + 1];
                }
                f[i][j] = Matrix.multiply(f[i - 1][j], buildMatrix(i - 1, j));
            }
        }

        long current = 0;
        long power = 1;

        --digits_count;
        for (int i = 0; i < digits_count; ++i) {
            power *= k;
        }

        Matrix result = new Matrix();
        for (int i = 0; i <= k; ++i) {
            result.mat[i][i] = 1;
        }

        while (current < n) {
            // The assert in C++ is replaced with an if to mimic behavior
            if (digits_count < 0) {
                break;
            }
            while (current + power <= n) {
                result = Matrix.multiply(result, buildMatrix(digits_count, digit_sum(current)));
                current += power;
            }
            power /= k;
            --digits_count;
        }

        int total = 0;
        for (int i = 0; i <= k; ++i) {
            total = sum_mod(total, result.mat[k][i]);
        }
        System.out.println(total);
        sc.close();
    }
}

